// No inputs. Call and sanity-check constant return. Do not attempt to free/modify it.
const char *ver = opj_version();
// Property: implementation must return a non-null C string
FUZZ_ASSERT(ver != nullptr, "opj_version returned null");
// Optionally touch the first byte to ensure memory is readable (no modification)
volatile char c = ver[0]; (void)c;

// Build a small array of component parameters and a valid color space.
// Constrain numcmpts to 1..4 to keep allocations tiny.
OPJ_UINT32 numcmpts = (OPJ_UINT32)(*FUZZ_PARAM(unsigned int) % 4u) + 1u;
opj_image_cmptparm_t cmptparms[4];
for (OPJ_UINT32 i = 0; i < numcmpts; ++i) {
    // Set minimal, valid geometry and sampling
    cmptparms[i].dx = 1; cmptparms[i].dy = 1;
    cmptparms[i].w = (OPJ_UINT32)((*FUZZ_PARAM(unsigned int) % 32u) + 1u);
    cmptparms[i].h = (OPJ_UINT32)((*FUZZ_PARAM(unsigned int) % 32u) + 1u);
    cmptparms[i].x0 = 0; cmptparms[i].y0 = 0;
    cmptparms[i].prec = (OPJ_UINT32)((*FUZZ_PARAM(unsigned int) % 16u) + 1u); // 1..17 bits
    cmptparms[i].sgnd = (OPJ_UINT32)(*FUZZ_PARAM(unsigned int) % 2u);
}
// Choose a color space from known values
OPJ_COLOR_SPACE clrspc = (OPJ_COLOR_SPACE)((int[]){OPJ_CLRSPC_SRGB, OPJ_CLRSPC_GRAY, OPJ_CLRSPC_SYCC}[*FUZZ_PARAM(unsigned int) % 3]);
// Create the image
opj_image_t *image = opj_image_create(numcmpts, cmptparms, clrspc);
if (!image) { FUZZ_BAIL(); }
// Track ownership/lifetime for safe destruction later
FUZZ_SET_ATTR_STR(image, "creator", "opj_image_create");

// Ensure this image was created by an OpenJPEG creator in our harness.
const char *creator = FUZZ_GET_ATTR_STR(image, "creator");
if (!(creator && creator[0])) { FUZZ_BAIL(); }
// Destroy and drop from pool. Do not use after this.
opj_image_destroy(image);

// Create a tile image skeleton: similar constraints as opj_image_create
OPJ_UINT32 numcmpts = (OPJ_UINT32)(*FUZZ_PARAM(unsigned int) % 4u) + 1u;
opj_image_cmptparm_t cmptparms[4];
for (OPJ_UINT32 i = 0; i < numcmpts; ++i) {
    cmptparms[i].dx = 1; cmptparms[i].dy = 1;
    cmptparms[i].w = (OPJ_UINT32)((*FUZZ_PARAM(unsigned int) % 64u) + 1u);
    cmptparms[i].h = (OPJ_UINT32)((*FUZZ_PARAM(unsigned int) % 64u) + 1u);
    cmptparms[i].x0 = 0; cmptparms[i].y0 = 0;
    cmptparms[i].prec = (OPJ_UINT32)((*FUZZ_PARAM(unsigned int) % 16u) + 1u);
    cmptparms[i].sgnd = (OPJ_UINT32)(*FUZZ_PARAM(unsigned int) % 2u);
}
OPJ_COLOR_SPACE clrspc = (OPJ_COLOR_SPACE)((int[]){OPJ_CLRSPC_SRGB, OPJ_CLRSPC_GRAY}[*FUZZ_PARAM(unsigned int) % 2]);
opj_image_t *image = opj_image_tile_create(numcmpts, cmptparms, clrspc);
if (!image) { FUZZ_BAIL(); }
// Track origin for destruction and later data allocation pairing
FUZZ_SET_ATTR_STR(image, "creator", "opj_image_tile_create");

// Allocate a small buffer. Keep <= 2048 bytes for perf.
OPJ_SIZE_T sz = (OPJ_SIZE_T)((*FUZZ_PARAM(unsigned int) % 2048u) + 1u);
void *buf = opj_image_data_alloc(sz);
if (!buf) { FUZZ_BAIL(); }
// Track allocation size and origin to ensure correct freeing later
FUZZ_SET_ATTR_INT((void*)buf, "image_data_alloc", 1);
FUZZ_SET_ATTR_INT((void*)buf, "size", (int)sz);

// Ensure pointer came from opj_image_data_alloc and hasn't been freed yet
if (FUZZ_GET_ATTR_INT((void*)ptr, "image_data_alloc") != 1) { FUZZ_BAIL(); }
// Free and drop. Clear the attribute by not returning it.
opj_image_data_free(ptr);

// Randomly choose direction: OPJ_TRUE=input(read), OPJ_FALSE=output(write)
OPJ_BOOL is_input = (OPJ_BOOL)(*FUZZ_PARAM(unsigned int) & 1u);
opj_stream_t *stream = opj_stream_default_create(is_input);
if (!stream) { FUZZ_BAIL(); }
// Track direction and validity
FUZZ_SET_ATTR_INT(stream, "direction", is_input ? 1 : 0);
FUZZ_SET_ATTR_INT(stream, "valid", 1);

// Choose a modest internal buffer size and a direction
OPJ_SIZE_T buf_sz = (OPJ_SIZE_T)((*FUZZ_PARAM(unsigned int) % 1024u) + 1u);
OPJ_BOOL is_input = (OPJ_BOOL)(*FUZZ_PARAM(unsigned int) & 1u);
opj_stream_t *stream = opj_stream_create(buf_sz, is_input);
if (!stream) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(stream, "direction", is_input ? 1 : 0);
FUZZ_SET_ATTR_INT(stream, "valid", 1);
FUZZ_SET_ATTR_INT(stream, "buf_sz", (int)buf_sz);

// Only destroy streams we know are valid to avoid double free
if (FUZZ_GET_ATTR_INT(stream, "valid") != 1) { FUZZ_BAIL(); }
opj_stream_destroy(stream);
// Drop from pool by not returning it

// p_stream must be valid; user_data is opaque. We pass no free callback (NULL) to avoid double-free.
if (FUZZ_GET_ATTR_INT(stream, "valid") != 1) { FUZZ_BAIL(); }
// Ensure user_data is a stable pointer we manage (e.g., from opj_image_data_alloc)
if (FUZZ_GET_ATTR_INT((void*)user_data, "image_data_alloc") != 1) { FUZZ_BAIL(); }
opj_stream_set_user_data(stream, user_data, (opj_stream_free_user_data_fn)NULL);
// Track association without transferring ownership (no free callback set)
FUZZ_SET_ATTR_PTR(stream, "user_data", (void*)user_data);

// p_stream must be valid
if (FUZZ_GET_ATTR_INT(stream, "valid") != 1) { FUZZ_BAIL(); }
// Use a small random length; if unknown length desired, we may also set 0 sometimes
OPJ_UINT64 len = (OPJ_UINT64)((*FUZZ_PARAM(unsigned int) % 2u) ? 0u : (OPJ_UINT64)((*FUZZ_PARAM(unsigned int) % 4096u)));
opj_stream_set_user_data_length(stream, len);
FUZZ_SET_ATTR_INT(stream, "user_data_len_set", 1);

// Create a file-backed stream using a fuzzer-provided filename
const char *fname = FUZZ_PARAM_FILENAME();
OPJ_BOOL is_read = (OPJ_BOOL)(*FUZZ_PARAM(unsigned int) & 1u);
opj_stream_t *stream = opj_stream_create_default_file_stream(fname, is_read);
if (!stream) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(stream, "direction", is_read ? 1 : 0);
FUZZ_SET_ATTR_INT(stream, "valid", 1);
FUZZ_SET_ATTR_STR(stream, "creator", "default_file_stream");

// Create a file-backed stream with explicit internal buffer size
const char *fname = FUZZ_PARAM_FILENAME();
OPJ_SIZE_T buf_sz = (OPJ_SIZE_T)((*FUZZ_PARAM(unsigned int) % 1024u) + 1u);
OPJ_BOOL is_read = (OPJ_BOOL)(*FUZZ_PARAM(unsigned int) & 1u);
opj_stream_t *stream = opj_stream_create_file_stream(fname, buf_sz, is_read);
if (!stream) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(stream, "direction", is_read ? 1 : 0);
FUZZ_SET_ATTR_INT(stream, "valid", 1);
FUZZ_SET_ATTR_INT(stream, "buf_sz", (int)buf_sz);
FUZZ_SET_ATTR_STR(stream, "creator", "file_stream");

// Choose a supported decode format randomly
OPJ_CODEC_FORMAT fmt_choices[3] = { OPJ_CODEC_J2K, OPJ_CODEC_JP2, OPJ_CODEC_JPT };
OPJ_CODEC_FORMAT fmt = fmt_choices[*FUZZ_PARAM(unsigned int) % 3];
opj_codec_t *codec = opj_create_decompress(fmt);
if (!codec) { FUZZ_BAIL(); }
// Track role and validity
FUZZ_SET_ATTR_STR(codec, "role", "decoder");
FUZZ_SET_ATTR_INT(codec, "valid", 1);
FUZZ_SET_ATTR_INT(codec, "decoder_setup", 0);
FUZZ_SET_ATTR_INT(codec, "read_header_done", 0);
FUZZ_SET_ATTR_INT(codec, "tile_header_ready", 0);

// Only destroy codecs we created and haven't destroyed yet
if (FUZZ_GET_ATTR_INT(codec, "valid") != 1) { FUZZ_BAIL(); }
// Destroy and drop from pool
opj_destroy_codec(codec);

// Must be a valid decoder and part of an active decoding session
if (FUZZ_GET_ATTR_INT(codec, "valid") != 1) { FUZZ_BAIL(); }
if (strcmp(FUZZ_GET_ATTR_STR(codec, "role"), "decoder") != 0) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(stream, "valid") != 1) { FUZZ_BAIL(); }
// Ensure this stream is the one associated with this codec
void *sess_stream = FUZZ_GET_ATTR_PTR(codec, "stream");
if (sess_stream && sess_stream != (void*)stream) { FUZZ_BAIL(); }
OPJ_BOOL ok = opj_end_decompress(codec, stream);
if (!ok) { FUZZ_BAIL(); }

// Allocate a decoder parameter block and initialize with defaults
opj_dparameters_t *parameters = new opj_dparameters_t();
opj_set_default_decoder_parameters(parameters);
// Track initialization
FUZZ_SET_ATTR_INT(parameters, "decoder_defaults", 1);

// Preconditions: valid decoder, parameters initialized with defaults
if (FUZZ_GET_ATTR_INT(codec, "valid") != 1) { FUZZ_BAIL(); }
if (strcmp(FUZZ_GET_ATTR_STR(codec, "role"), "decoder") != 0) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(parameters, "decoder_defaults") != 1) { FUZZ_BAIL(); }
OPJ_BOOL ok = opj_setup_decoder(codec, parameters);
if (!ok) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(codec, "decoder_setup", 1);

// Must be a configured decoder
if (FUZZ_GET_ATTR_INT(codec, "valid") != 1) { FUZZ_BAIL(); }
if (strcmp(FUZZ_GET_ATTR_STR(codec, "role"), "decoder") != 0) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(codec, "decoder_setup") != 1) { FUZZ_BAIL(); }
